arguments.file_text:
namespace sv_21d208988c61422ebe8960a392db5384.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies subscribers when it changes.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to call StateHasChanged.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Bulk-set both values (e.g. when hydrating from sessionStorage)
    /// without firing the event twice.
    /// </summary>
    public void SetAll(ThemeMode theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

// Thin sessionStorage wrapper called from Blazor JS interop.
// sessionStorage is per-tab, so each browser tab is independent.

export function getTheme() {
    return sessionStorage.getItem('app_theme') ?? 'System';
}

export function setTheme(value) {
    sessionStorage.setItem('app_theme', value);
}

export function getAccentColor() {
    return sessionStorage.getItem('app_accentColor') ?? '#0d6efd';
}

export function setAccentColor(value) {
    sessionStorage.setItem('app_accentColor', value);
}

export function applyThemeToDocument(theme, accentColor) {
    // Resolve "System" to the OS preference
    let effective = theme;
    if (theme === 'System') {
        effective = window.matchMedia('(prefers-color-scheme: dark)').matches
            ? 'Dark' : 'Light';
    }
    document.documentElement.setAttribute('data-bs-theme', effective.toLowerCase());
    document.documentElement.style.setProperty('--app-accent-color', accentColor);
}

@*
    Interactive island embedded in the static layout.
    It hydrates theme from sessionStorage on init, pushes it into the
    scoped ThemeService, and re-renders whenever the service fires OnChange.
*@
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeSvc
@inject IJSRuntime JS

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @ThemeIcon @ThemeSvc.Theme
</span>

<button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme" title="Toggle theme">
    🔄
</button>

@code {
    private IJSObjectReference? _module;

    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./js/theme-interop.js");

        // Hydrate from sessionStorage so theme persists across navigations
        var storedTheme = await _module.InvokeAsync<string>("getTheme");
        var storedAccent = await _module.InvokeAsync<string>("getAccentColor");

        var theme = Enum.TryParse<ThemeMode>(storedTheme, true, out var t)
            ? t : ThemeMode.System;

        ThemeSvc.SetAll(theme, storedAccent);
        await ApplyToDom();

        ThemeSvc.OnChange += OnThemeChanged;
        StateHasChanged();
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await PersistAndApply();
            StateHasChanged();
        });
    }

    private async Task CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
        // PersistAndApply is triggered via OnThemeChanged
    }

    private async Task PersistAndApply()
    {
        if (_module is null) return;
        await _module.InvokeVoidAsync("setTheme", ThemeSvc.Theme.ToString());
        await _module.InvokeVoidAsync("setAccentColor", ThemeSvc.AccentColor);
