toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeSvc
@inject IJSRuntime JS

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var active = ThemeSvc.Theme == mode;
                <button type="button"
                        class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SetTheme(mode)">
                    @(mode switch
                    {
                        ThemeMode.Light => "☀️ Light",
                        ThemeMode.Dark  => "🌙 Dark",
                        _               => "💻 System"
                    })
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnAccentChanged"
                   title="Choose accent color" />
            <span style="color: @ThemeSvc.AccentColor; font-weight: bold;">
                @ThemeSvc.AccentColor
            </span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeSvc.Theme</strong><br />
            Accent: <span style="color: @ThemeSvc.AccentColor;">■ @ThemeSvc.AccentColor</span>
        </p>
    </div>
</div>

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./js/theme-interop.js");

        ThemeSvc.OnChange += OnThemeChanged;
        StateHasChanged();
    }

    private void SetTheme(ThemeMode mode)
    {
        ThemeSvc.Theme = mode;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public async ValueTask DisposeAsync()
    {
        ThemeSvc.OnChange -= OnThemeChanged;
        if (_module is not null)
            await _module.DisposeAsync();
    }
}

